import React, { useState } from 'react';
import './styles/style.css'; // Przekształcamy wszystkie style na CSS
import { Link } from 'react-router-dom'; // Dla nawigacji

interface ItemAddProps {
  username: string;
  avatar: string;
  onLogout: () => void;
  onNavigateToList: () => void;
}

const wearLevels = ["Factory New", "Minimal Wear", "Field-Tested", "Well-Worn", "Battle-Scarred"];

const ItemAdd: React.FC<ItemAddProps> = ({ username, avatar, onLogout, onNavigateToList }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isUserMenuOpen, setIsUserMenuOpen] = useState(false);
  const [itemName, setItemName] = useState('');
  const [selectedType, setSelectedType] = useState('');
  const [condition, setCondition] = useState('');
  const [isFilterVisible, setIsFilterVisible] = useState(false);
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [images, setImages] = useState<{ [key: string]: string }>({});
  const [showSuggestions, setShowSuggestions] = useState(false);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  const toggleUserMenu = () => {
    setIsUserMenuOpen(!isUserMenuOpen);
  };

  const handleLogout = () => {
    if (window.confirm("Czy na pewno chcesz się wylogować?")) {
      onLogout();
    }
  };

  const handleSearch = async () => {
    setShowSuggestions(false);
    setImages({});
    
    const isStatTrak = selectedType === 'StatTrak™';
    const isSouvenir = selectedType === 'Souvenir';
    const queryParams = new URLSearchParams({
      query: itemName
    });

    if (condition) {
      queryParams.append('condition', condition);
    }
    if (isStatTrak) {
      queryParams.append('stattrak', 'true');
    }
    if (isSouvenir) {
      queryParams.append('souvenir', 'true');
    }

    fetch(`http://127.0.0.1:8000/suggestions?${queryParams.toString()}`)
      .then((response) => response.json())
      .then((data) => {
        const newSuggestions: any[] = [];
        const newImages: { [key: string]: string } = {};

        for (const suggestion of data) {
          if (suggestion.imageurl) {
            newSuggestions.push(suggestion);
            newImages[suggestion.display_fullname] = suggestion.imageurl;
          }
        }

        setSuggestions(newSuggestions);
        setImages(newImages);
        setShowSuggestions(true);
      })
      .catch((error) => {
        console.error('Błąd podczas pobierania sugestii:', error);
      });
  };

  return (
    <div className="container">
      <div className="menu">
        <button onClick={toggleMenu}>Menu</button>
        <img src="./assets/skinradar.png" alt="logo" className="logo" />
        <button onClick={toggleUserMenu}>
          <img src={avatar} alt="avatar" className="avatar" />
        </button>
      </div>

      {isMenuOpen && (
        <div className="dropdownMenu">
          <Link to="/" className="dropdownButton">LISTA</Link>
          <button className="dropdownButton">DODAJ</button>
        </div>
      )}

      {isUserMenuOpen && (
        <div className="userMenu">
          <p>{username}</p>
          <button onClick={handleLogout}>Wyloguj</button>
        </div>
      )}

      <div className="searchContainer">
        <input
          type="text"
          placeholder="Wpisz nazwę przedmiotu"
          value={itemName}
          onChange={(e) => setItemName(e.target.value)}
        />
        <button onClick={handleSearch}>Wyszukaj</button>
      </div>

      {showSuggestions && (
        <div className="suggestionsContainer">
          {suggestions.map((suggestion, index) => (
            <div key={index} className="suggestionItem">
              <h3>{suggestion.display_fullname}</h3>
              {suggestion.imageurl && <img src={suggestion.imageurl} alt="item" />}
            </div>
          ))}
        </div>
      )}

      <div className="menu2">
        {[...Array(3)].map((_, idx) => (
          <button key={idx} onClick={() => {}}>
            Icon {idx + 1}
          </button>
        ))}
      </div>
    </div>
  );
};

export default ItemAdd;
